SET lock_timeout = '5s';
-- CLN-004: versioned, region-scoped safety dictionary (allergy classes, brands, stems, not-the-stem exclusions,
-- pregnancy-risk and controlled lists). Regional REFERENCE data: no tenant_id (each regional cell holds its own
-- regions), owned by the migrator, SELECT-only for nabd_app. Content changes only through the SECURITY DEFINER
-- import / approve / activate functions below, which the internal endpoints call.
-- The matching algorithm stays in code (AllergyDrugClasses, RxSafetyChecks).

CREATE TABLE IF NOT EXISTS safety_dictionary_versions (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  region           text NOT NULL CHECK (region IN ('IN', 'SA', 'AE', 'QA')),
  version          int  NOT NULL CHECK (version >= 0),
  status           text NOT NULL CHECK (status IN ('draft', 'approved', 'active', 'retired')),
  checksum         text NOT NULL,
  labels           jsonb NOT NULL DEFAULT '{}'::jsonb,   -- {"controlled": {"en": "...", "ar": "..."}}
  cso_approval_ref text,
  approved_by      text,
  approved_at      timestamptz,
  activated_at     timestamptz,
  created_by       text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (region, version),
  CONSTRAINT safety_dictionary_approval_complete CHECK ((cso_approval_ref IS NULL) = (approved_at IS NULL)),
  CONSTRAINT safety_dictionary_approved_has_ref CHECK (status <> 'approved' OR cso_approval_ref IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS safety_dictionary_one_active ON safety_dictionary_versions (region) WHERE status = 'active';

CREATE TABLE IF NOT EXISTS safety_dictionary_entries (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  version_id      uuid NOT NULL REFERENCES safety_dictionary_versions (id),
  kind            text NOT NULL CHECK (kind IN ('allergy_class', 'pregnancy_risk', 'controlled', 'not_the_stem')),
  class_id        text,
  match_kind      text NOT NULL CHECK (match_kind IN ('term', 'stem')),
  value           text NOT NULL CHECK (btrim(value) <> ''),
  lang            text,
  cross_reacts_to text[] NOT NULL DEFAULT '{}',
  severity_hint   text,
  CONSTRAINT safety_dictionary_entry_class CHECK ((kind = 'allergy_class') = (class_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS safety_dictionary_entries_version_kind ON safety_dictionary_entries (version_id, kind);

-- New draft version from already-validated rows (SafetyDictionaryBundles.validate). Re-uploading content identical to
-- an existing version of the region returns that version instead of creating another (idempotent upload).
CREATE OR REPLACE FUNCTION safety_dictionary_import(p_region text, p_entries jsonb, p_labels jsonb, p_created_by text)
  RETURNS TABLE (version_id uuid, version int, checksum text, status text, created boolean)
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
#variable_conflict use_column
DECLARE
  v_checksum text := encode(sha256(convert_to(jsonb_build_object('entries', p_entries, 'labels', COALESCE(p_labels, '{}'::jsonb))::text, 'UTF8')), 'hex');
  v_latest safety_dictionary_versions%ROWTYPE;
  v_id uuid;
  v_version int;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('safety_dictionary:' || p_region));
  SELECT * INTO v_latest FROM safety_dictionary_versions d WHERE d.region = p_region AND d.checksum = v_checksum
   ORDER BY d.version DESC LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT v_latest.id, v_latest.version, v_latest.checksum, v_latest.status, false;
    RETURN;
  END IF;
  SELECT COALESCE(max(d.version) + 1, 0) INTO v_version FROM safety_dictionary_versions d WHERE d.region = p_region;
  INSERT INTO safety_dictionary_versions (region, version, status, checksum, labels, created_by)
  VALUES (p_region, v_version, 'draft', v_checksum, COALESCE(p_labels, '{}'::jsonb), p_created_by) RETURNING id INTO v_id;
  INSERT INTO safety_dictionary_entries (version_id, kind, class_id, match_kind, value, lang, cross_reacts_to)
  SELECT v_id, x.e->>'kind', x.e->>'classId', x.e->>'matchKind', x.e->>'value', x.e->>'lang',
         ARRAY(SELECT jsonb_array_elements_text(COALESCE(x.e->'crossReactsTo', '[]'::jsonb)))
  FROM jsonb_array_elements(p_entries) WITH ORDINALITY AS x(e, n) ORDER BY x.n;
  RETURN QUERY SELECT v_id, v_version, v_checksum, 'draft'::text, true;
END $$;

-- Records the CSO approval (reference to the signed approval record). A version is approved once; a draft becomes
-- 'approved', a retired or active version keeps its status (so an older version can be approved for rollback).
CREATE OR REPLACE FUNCTION safety_dictionary_approve(p_version_id uuid, p_ref text, p_by text) RETURNS boolean
  LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  WITH u AS (
    UPDATE safety_dictionary_versions
       SET cso_approval_ref = p_ref, approved_by = p_by, approved_at = now(),
           status = CASE WHEN status = 'draft' THEN 'approved' ELSE status END
     WHERE id = p_version_id AND cso_approval_ref IS NULL
    RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM u);
$$;

-- Activation and rollback are the same move: the region's active version is retired and the target becomes active,
-- in one transaction under the region lock. Refuses an unapproved or already-active target.
CREATE OR REPLACE FUNCTION safety_dictionary_activate(p_version_id uuid)
  RETURNS TABLE (outcome text, region text, version int, previous_version int)
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
#variable_conflict use_column
DECLARE
  t safety_dictionary_versions%ROWTYPE;
  prev int;
BEGIN
  SELECT * INTO t FROM safety_dictionary_versions d WHERE d.id = p_version_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found'::text, NULL::text, NULL::int, NULL::int;
    RETURN;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('safety_dictionary:' || t.region));
  SELECT * INTO t FROM safety_dictionary_versions d WHERE d.id = p_version_id;
  IF t.status = 'active' THEN
    RETURN QUERY SELECT 'already_active'::text, t.region, t.version, NULL::int;
    RETURN;
  END IF;
  IF t.cso_approval_ref IS NULL THEN
    RETURN QUERY SELECT 'not_approved'::text, t.region, t.version, NULL::int;
    RETURN;
  END IF;
  UPDATE safety_dictionary_versions d SET status = 'retired' WHERE d.region = t.region AND d.status = 'active'
  RETURNING d.version INTO prev;
  UPDATE safety_dictionary_versions d SET status = 'active', activated_at = now() WHERE d.id = p_version_id;
  RETURN QUERY SELECT 'activated'::text, t.region, t.version, prev;
END $$;

REVOKE ALL ON FUNCTION safety_dictionary_import(text, jsonb, jsonb, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION safety_dictionary_approve(uuid, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION safety_dictionary_activate(uuid) FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'nabd_app') THEN
    REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON safety_dictionary_versions, safety_dictionary_entries FROM nabd_app;
    GRANT SELECT ON safety_dictionary_versions, safety_dictionary_entries TO nabd_app;
    GRANT EXECUTE ON FUNCTION safety_dictionary_import(text, jsonb, jsonb, text) TO nabd_app;
    GRANT EXECUTE ON FUNCTION safety_dictionary_approve(uuid, text, text) TO nabd_app;
    GRANT EXECUTE ON FUNCTION safety_dictionary_activate(uuid) TO nabd_app;
  END IF;
END $$;

